const e={title:"TripReel - Безкоштовний Додаток для Анімації Подорожей: Перетворіть Фото на Красиві Відео",description:"Створюйте приголомшливі відео подорожей з анімованими картами та маршрутами польотів. Безкоштовний додаток для анімації подорожей з 3D-картографією маршрутів глобусу. Автоматично перетворіть свої фото на красиві відео подорожей. Конфіденційність на першому місці, працює офлайн.",keywords:"додаток для анімації подорожей, додаток для анімації карти подорожей, додаток для анімації маршруту подорожей, додаток для анімації польоту, творець відео подорожей, автоматичне відео подорожей, анімована карта подорожей, анімація маршруту польоту, анімація подорожей, анімація глобусу, відео огляду подорожей, фото у відео, highlights подорожей, безкоштовний додаток для подорожей, творець відео офлайн, приватний додаток для подорожей, відео плівки камери"},t={logoAlt:"Логотип TripReel",appName:"TripReel",howItWorks:"Як це працює",video:"Відео",features:"Функції",theApp:"Додаток"},i={badge:"Перетворіть фото на подорожні історії",title1:"Ваша галерея фото,",title2:"Повністю використана",description:"TripReel автоматично створює красиві подорожні відео з локацій ваших фотографій. Спостерігайте, як ваші подорожі оживають із приголомшливими анімованими картами маршрутів і польотними шляхами на 3D-глобусі, поки ваші дані залишаються приватними та захищеними.",secure:"100% безпечно",worksOffline:"Працює офлайн",globeAlt:"Анімація глобуса TripReel"},o={title:"Як це працює",subtitle:"Три прості кроки для створення ідеального подорожнього відео",step1:{title:"Дозвольте доступ до фото",description:"Надайте TripReel доступ до вашої бібліотеки фотографій. Додаток читає лише метадані локацій, нічого іншого."},step2:{title:"Автоматичне виявлення подорожей",description:"TripReel аналізує метадані локацій і розумно знаходить ваші подорожі на основі дат і місць."},step3:{title:"Створіть своє відео",description:"Спостерігайте, як ваша подорож розгортається на красивій анімації глобуса, готовій до поширення в соціальних мережах."}},r={title:"Побачте магію в дії",subtitle:"Дивіться, як TripReel перетворює вашу бібліотеку фотографій на вражаючі подорожні відео",caption:"Ось так виглядатиме ваше фінальне подорожнє відео"},s={title:"Все, що вам потрібно",subtitle:"Потужні функції, розроблені для сучасних мандрівників",twoTap:{title:"Подорожні відео двома дотиками",description:"Створюйте приголомшливі подорожні відео з вашої бібліотеки фотографій лише двома дотиками. Без редагування."},smartTrip:{title:"Розумне виявлення подорожей",description:"Автоматично знаходить і групує ваші подорожі, аналізуючи дати та метадані локацій з ваших фотографій."},globe:{title:"Красива анімація глобуса",description:"Спостерігайте, як ваша подорож оживає з приголомшливим 3D-глобусом, що показує ваші анімовані туристичні маршрути та польотні шляхи по всьому світу."},privacy:{title:"Конфіденційність на першому місці",description:"Все обробляється на вашому пристрої. Ваші фотографії ніколи не залишають ваш телефон. Працює в режимі польоту."},customStyles:{title:"Власні стилі",description:"Виберіть з кількох стилів земної кулі та налаштувань, щоб відповідати вашій естетиці та зробити кожне відео унікальним."},manualControl:{title:"Ручне керування",description:"Ви можете вручну додавати абсолютно нові подорожі, якщо служби геолокації не були увімкнені на вашому пристрої."}},l={title:"Креативні ідеї відео",subtitle:"Отримайте натхнення з того, що ви можете створити за допомогою TripReel. Від коротких вихідних до цілорічних пригод, створюйте приголомшливі подорожні відео для кожної подорожі.",description:"Чи створюєте ви анімацію карти подорожі, документуєте маршрут польоту чи робите підсумок подорожей за рік, TripReel полегшує перетворення ваших спогадів на відео для поширення.",ideas:{yearRecap:{title:"Підсумок подорожей 2025",description:"Створіть відео річного підсумку подорожей за 2025 рік автоматично"},europeRoadTrip:{title:"Автомандрівка Європою",description:"Продемонструйте свою європейську пригоду з анімованими картами маршрутів"},southeastAsia:{title:"Подорож Південно-Східною Азією",description:"Візуалізуйте свій маршрут з рюкзаком через кілька країн"},japanRail:{title:"Залізнична подорож Японією",description:"Створіть відео карт ваших залізничних маршрутів по Японії"},crossCountry:{title:"Через США",description:"Перетворіть свою американську автомандрівку на епічне відео маршруту"},islandHopping:{title:"Стрибки островами",description:"Покажіть свої подорожі з острова на острів з приголомшливими 3D-анімаціями"},worldTour:{title:"Монтаж світового туру",description:"Кілька подорожей в одне вражаюче глобальне відео подорожі"},travelPlans:{title:"Плани подорожей 2026",description:"Візуалізуйте та сплануйте свої захоплюючі подорожні пригоди на 2026 рік"},lifetimeTravel:{title:"Історія подорожей життя",description:"Створіть відео, що демонструє всі ваші подорожі протягом життя"},regionalExplorer:{title:"Регіональний дослідник",description:"Картографуйте свої пригоди через штати, провінції та регіони"},festivalCircuit:{title:"Фестивальний тур",description:"Картографуйте свою подорож музичними фестивалями та подіями"},bikeRoutes:{title:"Мої міські подорожі",description:"Покажіть усі свої міські втечі"}}},a={title:"Додаток",subtitle:"Доступно зараз в App Store",alt1:"Автоматичні подорожні відео - Створюйте вражаючі відео за секунди",alt2:"Виявлення локації фото - Використовує метадані ваших фотографій",alt3:"Виявлення подорожей - Автоматично групує ваші подорожі",alt4:"Красиві відео Землі - Анімація глобуса вашої подорожі",alt5:"Власні стилі - Персоналізуйте ваші подорожні відео"},n={comingSoon:"Незабаром",androidTitle:"Додаток для Android незабаром!",androidMessage:'Версія для Android ще не доступна, але скоро буде. Напишіть мені на <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a>, і я повідомлю вас, коли вона буде готова!',gotIt:"Зрозуміло!"},p={title:"Часті запитання",subtitle:"Все, що вам потрібно знати про TripReel",q1:{question:"Чи можу я справді використовувати додаток повністю в режимі польоту?",answer:"Так! Для преміум-користувачів додаток можна використовувати повністю офлайн у режимі польоту без обмежень. Для не-преміум користувачів деякі функції підтримуються рекламою, яка може вимагати тимчасового ввімкнення інтернету, але для преміум-користувачів немає реклами, і додаток можна повністю використовувати в режимі польоту."},q2:{question:"Я оновився до Преміум, як я можу видалити водяний знак?",answer:"Багато людей запитують, який додаток використовувався для створення цих відео, тому після оновлення до преміуму у вас є можливість додати меншу версію водяного знака (лише з назвою додатка) або повністю видалити його, якщо бажаєте."},q3:{question:"Чи безпечні та приватні мої дані фотографій?",answer:"Абсолютно! TripReel читає лише метадані локацій з ваших фотографій - ми ніколи не отримуємо доступ, не зберігаємо і не передаємо фактичний вміст фотографій. Вся обробка відбувається локально на вашому пристрої, і жодні дані ніколи не залишають ваш телефон. Ви можете перевірити це, використовуючи додаток у режимі польоту - він працює ідеально офлайн!"},q4:{question:"Що робити, якщо мої фотографії не мають даних про локацію?",answer:"Не проблема! Якщо служби геолокації не були ввімкнені, коли ви робили фотографії, ви можете вручну створити подорожі та додати локації самостійно. Додаток дає вам повний контроль для налаштування вашої часової шкали подорожей."},q5:{question:"Як додаток автоматично виявляє мої подорожі?",answer:"TripReel аналізує метадані локацій і часові позначки з ваших фотографій, щоб розумно визначити, коли і куди ви подорожували. Він групує близькі локації та дати разом для автоматичного виявлення ваших подорожей без необхідності ручної роботи."},q6:{question:"Чи можу я налаштувати зовнішній вигляд моїх відео?",answer:"Так! Ви можете вибрати з кількох стилів земної кулі та налаштувати різні аспекти ваших анімованих подорожніх відео, щоб відповідати вашій особистій естетиці. Преміум-користувачі отримують доступ до додаткових стилів анімації маршрутів, тем карт та опцій польотних шляхів."},q7:{question:"Чи потрібно мені створювати обліковий запис?",answer:"Обліковий запис не потрібен! TripReel працює відразу після завантаження. Немає реєстрації, немає входу, і не потрібна особиста інформація. Просто завантажте додаток і почніть створювати свої подорожні відео відразу."},q8:{question:"Чому локація відсутня в моїй подорожі?",answer:"Додаток може працювати лише з доступними даними, тому насамперед вам потрібно щонайменше кілька фотографій у цій локації. По-друге, вам потрібно переконатися, що у вас були ввімкнені дані про локацію, коли ви там були. По-третє, іноді погане приймання GPS може спричинити неправильні дані про локацію. Якщо ви виключили все це, і ваша локація все ще не з'являється, ви можете вручну додати цю локацію з Trips Overview > кнопка Edit. Будь ласка, також використовуйте Contact для повідомлення про проблему."},q9:{question:"Де я можу поділитися своїм чудовим відео?",answer:"Звичайно, ви також можете поділитися ним на всіх соціальних платформах. Щоб краще підходити до платформи, додаток дозволяє різні співвідношення сторін для ваших відео."},q10:{question:"Де я можу повідомити про помилку?",answer:"Просто зв'яжіться зі мною безпосередньо за адресою marian@qod.ee, коротко пояснивши, в чому проблема."}},c={title:"Підтримка електронною поштою",description:"Якщо у вас є будь-які відгуки або ви зіткнулися з будь-якими проблемами, будь ласка, не соромтеся зв'язатися зі мною безпосередньо на цю електронну адресу, і я особисто прочитаю та оброблю ваш запит якнайшвидше. Дякую за використання додатка!",close:"Закрити"},d={default:{title:"🍪 Файли cookie",message:"Ми використовуємо файли cookie на сайті TripReel для покращення вашого досвіду. Персональні дані не збираються.",accept:"Прийняти",decline:"Відхилити",details:"Деталі"},theme:{title:"🍪 Файли cookie",message:"🌙 Щоб зберегти вашу перевагу теми, вам потрібно прийняти основні файли cookie на сайті TripReel. Без них ваш вибір теми не може бути збережений.",accept:"Прийняти",decline:"Відхилити",details:"Деталі"}},u={privacy:"Політика конфіденційності додатка",cookies:"Політика cookie сайту",contact:"Контакт",cookiePreferences:"Налаштування cookie",madeWith:"Створено з",forTravelers:"для мандрівників по всьому світу",copyright:"© {{year}} TripReel."},T={title:"Готові поділитися своєю подорожжю?",description:"Завантажте TripReel сьогодні та перетворіть свою галерею фотографій на красиві подорожні відео з анімованими картами та маршрутами. Ваші пригоди заслуговують на святкування.",features:"Безкоштовно завантажити • Швидко та зручно • Гарантована конфіденційність"},R={title:"Про TripReel",subtitle:"Професійний створювач відео-підсумків подорожей та додаток для анімації маршрутів",howItWorks:{title:"Як працює наш додаток для резюме подорожей",description:"Додаток анімації подорожей використовує розумні алгоритми для сканування GPS-даних ваших фотографій та автоматичного виявлення ваших подорожей. Аніматор маршруту подорожі потім створює плавні, кінематографічні анімації маршруту подорожі, що показують ваш шлях містами, країнами та континентами. Чи створюєте ви швидке відео-підсумок подорожі на вихідні, чи річне відео-резюме подорожі, додаток анімованої карти подорожей робить це легко."},customization:{title:"Широке налаштування для ваших відео анімації подорожей",description:"Додаток створення історій подорожей пропонує параметри налаштування професійного рівня, щоб зробити ваші відео анімованої карти подорожей справді унікальними:",features:{videoQuality:"Виберіть між 30 FPS, 60 FPS або преміум 90 FPS для шовковисто-плавних анімацій маршруту подорожі у ваших відео-підсумках подорожей",bitrate:"Налаштуйте якість відео (бітрейт) від звичайної до високої для кришталево чистих відео подорожі на карті без візуальних артефактів",earthStyles:"Виберіть з кількох приголомшливих стилів Землі, включаючи Реалістичний, Нічні вогні, Денну карту та супутникові перегляди для ваших відео анімованої карти подорожей",borders:"Перемикайте кордони країн на вашому аніматорі маршруту подорожі з налаштовуваними кольорами та товщиною для покращеної візуалізації географії",aspectRatios:"Створюйте відео анімації подорожей у форматах Вертикальний (9:16), Широкоекранний (16:9), Кіно (2.35:1) або Квадратний (1:1), ідеальних для Instagram, TikTok, YouTube та інших соціальних платформ",tripSpeed:"Керуйте швидкістю аніматора маршруту подорожі між локаціями (до 3500 км/с) для створення динамічних або розслаблених відео-резюме подорожей",pauseDuration:"Налаштуйте тривалість паузи в кожному місці (0,5-5 секунд), щоб виділити важливі напрямки у ваших відео-підсумках подорожей",locationLabels:"Відображайте мітки Місто, Регіон та/або Країна на ваших відео анімованої карти подорожей, щоб надати контекст вашій подорожі",pathDisplay:"Перемикайте, чи хочете ви показувати всі минулі маршрути подорожей чи лише поточну подорож у вашій анімації маршруту подорожі"}}},q={meta:e,header:t,hero:i,howItWorks:o,videoSection:r,features:s,videoIdeas:l,screenshots:a,appStore:n,faq:p,contact:c,cookieBanner:d,footer:u,cta:T,about:R};export{R as about,n as appStore,c as contact,d as cookieBanner,T as cta,q as default,p as faq,s as features,u as footer,t as header,i as hero,o as howItWorks,e as meta,a as screenshots,l as videoIdeas,r as videoSection};
